'use strict';
function prepareBossAtlas(img){let canvas=document.createElement('canvas');canvas.width=img.width;canvas.height=img.height;let c=canvas.getContext('2d');c.drawImage(img,0,0);for(let rect of bossDetailRects){let [rx,ry,w,h]=rect,data=c.getImageData(rx,ry,w,h),pixels=data.data,seen=new Uint8Array(w*h),groups=[];for(let pos=0;pos<w*h;pos++){if(seen[pos]||pixels[pos*4+3]<30)continue;let queue=[pos],group=[],edge=false;seen[pos]=1;for(let q=0;q<queue.length;q++){let n=queue[q],x=n%w,y=Math.floor(n/w);group.push(n);if(x===0||y===0||x===w-1||y===h-1)edge=true;for(let next of [x>0?n-1:-1,x<w-1?n+1:-1,y>0?n-w:-1,y<h-1?n+w:-1])if(next>=0&&!seen[next]&&pixels[next*4+3]>=30){seen[next]=1;queue.push(next)}}groups.push({group,edge})}let largest=Math.max(1,...groups.map(g=>g.group.length));for(let g of groups)if(g.group.length<largest*.008||g.edge&&g.group.length<largest*.4)for(let n of g.group)pixels[n*4+3]=0;c.putImageData(data,rx,ry)}return canvas}

let bossDetailAtlas=null;const bossDetailRects=[[8, 57, 284, 186], [308, 61, 284, 177], [8, 356, 284, 187], [308, 356, 284, 187], [8, 654, 284, 191], [308, 656, 284, 187], [8, 959, 284, 182], [308, 959, 284, 181], [8, 1274, 284, 152], [308, 1270, 284, 160]];const bossDetailImage=new Image();bossDetailImage.onload=()=>bossDetailAtlas=prepareBossAtlas(bossDetailImage);bossDetailImage.src='data:image/webp;base64,';
